<?php $mode=$data['mode']; ?>
<div class="auth-wrap"><span class="eyebrow">WELCOME TO VEYRA</span><h1><?= ['login'=>'A place for your next chapter.','register'=>'Make yourself at home.','forgot'=>'Find your way back.','reset'=>'A fresh start.'][$mode] ?></h1><p><?= $mode==='register'?'One account for buying, renting, selling, and letting.':($mode==='login'?'Your homes, conversations, and possibilities, all in one place.':'Use a private, expiring reset link to update your password.') ?></p><form method="post" action="/<?= $mode ?>"><?= csrf() ?><?php if ($mode==='register'): ?><label class="field"><span>Your name</span><input name="name" autocomplete="name" minlength="2" maxlength="100" required></label><?php endif ?><?php if ($mode!=='reset'): ?><label class="field"><span>Email address</span><input type="email" name="email" autocomplete="email" required maxlength="190"></label><?php endif ?><?php if ($mode!=='forgot'): ?><label class="field"><span>Password<?= $mode==='login'?'':' (12 characters or more)' ?></span><input type="password" name="password" autocomplete="<?= $mode==='login'?'current-password':'new-password' ?>" <?= $mode!=='login'?'minlength="12"':'' ?> required></label><?php endif ?><?php if ($mode==='reset'): ?><input type="hidden" name="token" value="<?= e($_GET['token'] ?? '') ?>"><?php endif ?><button class="button"><?= ['login'=>'Sign in','register'=>'Create your account','forgot'=>'Request a reset','reset'=>'Set new password'][$mode] ?> <?= icon('arrow') ?></button></form><div class="auth-footer"><?php if ($mode==='login'): ?><a href="/forgot">Forgot your password?</a><p>New here? <a href="/register">Create an account</a></p><?php else: ?><a href="/login">Back to sign in</a><?php endif ?></div><?php if ($mode==='forgot'): ?><div class="notice">Email delivery is disabled. In local mode, reset links are saved outside the public directory for the operator. No email is sent.</div><?php endif ?></div>
